#!/usr/bin/env node
// Generates the GATEWAY icon output from the ONE canonical Gateway
// mark: src/app/icon.svg (the "ط" tile). This script owns exactly one
// tracked output — the Odoo addon's Apps-list icon (the addon fronts
// the Gateway, so it carries the Gateway mark). The Gateway web app
// itself serves the SVG directly.
//
// The Print Agent icons are a DIFFERENT mark and are generated by
// scripts/generate-agent-icons.mjs from
// src/desktop/public/brand/print-agent.svg. The two scripts previously
// shared one source file, which is why the Agent's exe/tray/installer
// all shipped the Gateway icon; they must never share a source again.
import sharp from "sharp";
import { readFile } from "fs/promises";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..");
const srcSvg = join(root, "src/app/icon.svg");
const odooIcon = join(root, "odoo_addons/print_gateway/static/description/icon.png");

async function main() {
  const svgBuf = await readFile(srcSvg);
  console.log(`Gateway icon source: src/app/icon.svg (${svgBuf.length} bytes)`);

  // Odoo icon 512
  await sharp(svgBuf)
    .resize(512, 512, { fit: "contain", background: { r: 0, g: 0, b: 0, alpha: 0 } })
    .png({ compressionLevel: 9 })
    .toFile(odooIcon);
  console.log("✓ odoo_addons/print_gateway/static/description/icon.png (512)");

  // The Gateway web app serves src/app/icon.svg directly; no PNG
  // favicon is tracked, and none is generated here.
  console.log("\nGateway icons generated. Agent icons: scripts/generate-agent-icons.mjs");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
